// ===========================================================================
//  CẤU HÌNH - watchlist kèm NGÀNH
// ===========================================================================
const WATCHLIST = [
  { t: 'BID', s: 'Ngân hàng' }, { t: 'VCB', s: 'Ngân hàng' }, { t: 'MBB', s: 'Ngân hàng' }, { t: 'STB', s: 'Ngân hàng' },
  { t: 'BCM', s: 'BĐS Khu công nghiệp' },
  { t: 'FPT', s: 'Công nghệ' },
  { t: 'VNM', s: 'Hàng tiêu dùng' }, { t: 'MWG', s: 'Bán lẻ' },
  { t: 'HPG', s: 'Thép (chu kỳ)' }, { t: 'DGC', s: 'Hoá chất' },
  { t: 'SSI', s: 'Chứng khoán' }, { t: 'VND', s: 'Chứng khoán' },
];
const FOCUS = ['BID', 'BCM', 'FPT'];
// ===========================================================================

// itemCode VNDirect: 51006=P/E, 51012=P/B, 51011=P/S, 51033=cổ tức, 51007=Beta,
// 1000041/42/43=P/E TB 1N/3N/5N, 1000048/49/50=P/B TB 1N/3N/5N, 1000068/70=% so đỉnh/đáy 52T
const ITEMCODES = '51006,51012,51011,51033,51007,51035,1000041,1000042,1000043,1000048,1000049,1000050,1000068,1000070';

const headers = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
  'Accept': 'application/json, text/plain, */*',
  'Referer': 'https://dstock.vndirect.com.vn/',
};

const fetchR = async (t) => {
  const url = 'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:' + t + '~itemCode:' + ITEMCODES + '&sort=reportDate:desc&size=80';
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url, headers, json: false, timeout: 15000 });
    let p; try { p = typeof res === 'string' ? JSON.parse(res) : res; } catch (e) { p = null; }
    return { data: (p && p.data) || [], raw: String(res).slice(0, 120) };
  } catch (e) {
    return { data: [], raw: 'ERR ' + (e.message || String(e)) };
  }
};

// Lấy giá trị MỚI NHẤT cho mỗi ratioCode (data đã sort reportDate desc -> lần đầu = mới nhất)
const latest = (data) => {
  const m = {};
  for (const d of data) { if (!(d.ratioCode in m)) m[d.ratioCode] = d.value; }
  return m;
};

const rows = [];
const debug = [];
for (const { t, s } of WATCHLIST) {
  const fr = await fetchR(t);
  if (!fr.data.length) { debug.push(t + ': RỖNG/lỗi (raw: ' + fr.raw + ')'); continue; }
  const m = latest(fr.data);
  rows.push({ t, s, m });
  const pe = m['PRICE_TO_EARNINGS'];
  debug.push(t + ': OK (' + Object.keys(m).length + ' chỉ số, P/E ' + (pe != null ? Number(pe).toFixed(1) : 'n/a') + ')');
}

const n2 = (v) => (v == null ? 'n/a' : Number(v).toFixed(1));
const pc = (v) => (v == null ? 'n/a' : (Number(v) * 100).toFixed(1) + '%');
let table = '';
for (const r of rows) {
  const m = r.m;
  table += (FOCUS.includes(r.t) ? '⭐ ' : '') + r.t + ' (' + r.s + '): '
    + 'P/E ' + n2(m['PRICE_TO_EARNINGS']) + ' (TB 1N/3N/5N: ' + n2(m['PRICE_TO_EARNINGS_AVG_CR_1Y']) + '/' + n2(m['PRICE_TO_EARNINGS_AVG_CR_3Y']) + '/' + n2(m['PRICE_TO_EARNINGS_AVG_CR_5Y']) + ')'
    + ' | P/B ' + n2(m['PRICE_TO_BOOK']) + ' (TB5N ' + n2(m['PRICE_TO_BOOK_AVG_CR_5Y']) + ')'
    + ' | P/S ' + n2(m['PRICE_TO_SALES'])
    + ' | Cổ tức ' + pc(m['DIVIDEND_YIELD'])
    + ' | Beta ' + n2(m['BETA'])
    + ' | 52T: ' + pc(m['PRICE_CHG_PCT_CR_HH52W']) + ' so đỉnh, ' + pc(m['PRICE_CHG_PCT_CR_LL52W']) + ' so đáy\n';
}

const today = new Date().toLocaleDateString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', day: 'numeric', month: 'numeric', year: 'numeric' });

const system = 'Bạn là chuyên viên phân tích ĐỊNH GIÁ cổ phiếu Việt Nam, theo trường phái biên an toàn (Graham/Buffett). '
  + 'Đánh giá mỗi mã RẺ / HỢP LÝ / ĐẮT dựa trên ĐỊNH GIÁ. Lưu ý: dữ liệu chưa có ROE/nợ nên chỉ kết luận về MỨC ĐỊNH GIÁ, KHÔNG khẳng định chất lượng doanh nghiệp.\n\n'
  + 'Bạn có 2 thước đo so sánh - DÙNG CẢ HAI:\n'
  + '1) So NGÀNH: Ngân hàng P/E ~6-12, P/B 1-2; Công nghệ/Bán lẻ P/E 15-25 nếu tăng trưởng tốt; Thép/Hoá chất CHU KỲ (P/E thấp lúc đỉnh LN là bẫy); Chứng khoán theo thị trường.\n'
  + '2) So LỊCH SỬ CHÍNH MÃ: P/E/P/B hiện tại so với trung bình 1N/3N/5N của nó. Thấp hơn nhiều TB nhiều năm = đang rẻ tương đối so với quá khứ (và ngược lại). Đây là tín hiệu biên an toàn quan trọng.\n\n'
  + 'Nguyên tắc bắt buộc:\n'
  + '- Mỗi mã: kết luận RẺ / HỢP LÝ / ĐẮT, nêu RÕ căn cứ từ CẢ so ngành LẪN so lịch sử của nó. Dùng Beta để nói về biến động/rủi ro; dùng vị trí 52 tuần để nói đang ở vùng cao hay thấp.\n'
  + '- Đọc kỹ 3 mã ⭐ (BID, BCM, FPT) - người dùng đang cân nhắc mua.\n'
  + '- CẢNH BÁO BẪY: P/E thấp ở mã chu kỳ (đỉnh lợi nhuận) = bẫy giá trị; P/E cao bất thường có thể do lợi nhuận tạm thấp; rẻ so lịch sử cũng có thể vì triển vọng xấu đi. ĐỪNG kết luận từ 1 chỉ số.\n'
  + '- Nhắc rõ: chưa có ROE/nợ nên CHƯA đánh giá được CHẤT LƯỢNG & sức khoẻ tài chính - người dùng cần kiểm chứng thêm bằng báo cáo tài chính gốc.\n'
  + '- KHÔNG bịa số. KHÔNG khuyến nghị mua/bán.\n'
  + '- Bố cục: (1) 💎 Xếp hạng RẺ → ĐẮT (kèm rẻ/đắt so lịch sử), (2) 🔎 Phân tích sâu BID/BCM/FPT, (3) ⚠️ Bẫy & điều cần kiểm chứng thêm.\n'
  + '- Markdown đơn giản, tối đa ~600 từ.';

const userContent = 'Ngày ' + today + '. Chỉ số định giá mới nhất (nguồn VNDirect). "TB 1N/3N/5N" = P/E trung bình 1/3/5 năm của CHÍNH mã. "52T" = % chênh so đỉnh/đáy 52 tuần:\n\n'
  + (table || '(không lấy được dữ liệu)')
  + '\n\nHãy viết báo cáo định giá theo đúng bố cục, dùng CẢ so ngành lẫn so lịch sử của từng mã.';

const requestBody = { model: 'claude-opus-4-8', max_tokens: 4000, system, messages: [{ role: 'user', content: userContent }] };

return [{ json: { requestBody, debug } }];

const res = $input.first().json;
let text = '';
if (res && Array.isArray(res.content)) text = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
if (!text) {
  if (res && res.type === 'error' && res.error) text = '⚠️ Lỗi API: ' + (res.error.message || JSON.stringify(res.error));
  else if (res && res.stop_reason === 'refusal') text = '⚠️ Bị từ chối bởi bộ lọc an toàn.';
  else text = '⚠️ Không tạo được báo cáo (phản hồi rỗng).';
}
const now = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
const full = '💎 *ĐỊNH GIÁ CƠ BẢN (Lớp 4)*\n_' + now + '_\n\n' + text + '\n\n_Chỉ số: VNDirect (gồm dải lịch sử P/E-P/B của chính mã) · Phân tích: Claude AI · chưa có ROE/nợ · KHÔNG phải khuyến nghị đầu tư_';
const SIZE = 3800;
const parts = [];
let s = full;
while (s.length > SIZE) { let cut = s.lastIndexOf('\n', SIZE); if (cut < SIZE * 0.5) cut = SIZE; parts.push(s.slice(0, cut)); s = s.slice(cut); }
if (s.trim()) parts.push(s);
return parts.map(p => ({ json: { message: p } }));
